//
// `not_held` - at the attested block, which is final, no deposit was present.
// Terminal. It does NOT say why, and MUST NOT be read as any particular history:
// the escrow's getter returns the same answer for a deposit that never existed, one
// already released and one already refunded, because both settlement paths delete
// the record before transferring. Telling those apart needs a log read rather than
// a state read and is not attested here. This matters because one of them means the
// recipient was already paid, so a consumer MUST NOT treat `not_held` as permission
// to pay anyone.
//
// `undetermined` - the chain was read successfully to the attested block, which is
// final, and the deposit's state could not be established. NOT terminal: the
// payment stays pending and is asked again.
//
// NOT EVERY UNKNOWN IS A VERDICT. When the chain could not be read at all there is
// no block to anchor a claim to, so no verdict is issued and the case is reported
// unsigned through the root `error`.
//
// A consumer MUST switch on the value and MUST NOT branch on `outcome != "held"`,
// which would turn a non-terminal answer into a terminal one. A value this enum does
// not list MUST be treated as no verdict, which is also the correct handling of
// `undetermined`, so a consumer built against a narrower form degrades safely.
type DepositVerdictOutcome string

// ErrorResponse Safe, outward-facing error derived from an internal error through the shared error catalog (schemas/apis/error/v1). The error shape these endpoints return for a handled failure.
//
// A panic is caught by gin's Recovery, which sends 500 with an empty body, so a 500 is not guaranteed to carry this shape.
type ErrorResponse struct {
	// Code Public, machine-readable error code in SCREAMING_SNAKE_CASE.
	Code string `json:"code"`

	// DocsUrl Link to the documentation page for this public code.
	DocsUrl *string `json:"docs_url,omitempty"`

	// Domain Originating service domain.
	Domain *string `json:"domain,omitempty"`

	// Message Curated, safe, human-readable message.
	Message string `json:"message"`

	// PaymentId The payment this error was raised against. Absent when the error is not about a specific payment.
	PaymentId *string `json:"payment_id,omitempty"`

	// RequestId Correlation id for locating the internal error record.
	RequestId *string `json:"request_id,omitempty"`

	// RequestIdReusable Whether the caller may re-send this same request_id. True means no payment was created for it, so the id is still free. False means a payment exists for it, so the id is spent and re-sending only replays this outcome. Absent means undetermined, which a caller should read as false. Separate from retry_classification, which answers what the caller must change rather than whether the id survived.
	RequestIdReusable *bool `json:"request_id_reusable,omitempty"`

	// RetryClassification What the caller should do next. Absent means the condition has not been classified, which is not the same as safe to retry.
	// Re-sending the same `request_id` is an idempotent replay and always safe. This value is about submitting a new one, which starts a new operation. See https://docs.atum.xyz/errors for the value set.
	RetryClassification *string `json:"retry_classification,omitempty"`
}

// EscrowsResponse Per-chain escrow contracts served by veri-fill.
type EscrowsResponse struct {
	// Chains One entry per chain this veri-fill instance serves and has an escrow configured for.
	Chains []ChainEscrows `json:"chains"`
}

// FinalityConfigResponse Per-chain finality configuration served by veri-fill.
type FinalityConfigResponse struct {
	// Chains One entry per chain this veri-fill instance is configured to verify.
	Chains []ChainFinalityConfig `json:"chains"`
}

// FulfillmentAuthorization Authorization for an originator to fulfill a payment request. The settler produces this declaration after authorizeFulfillment when the payment request's fulfill executor is "originator". A settler fulfill does not produce it.
//
// The route body is that declaration plus authorization_used and token_transfer. It is not the identity-signed document. The settler wraps the declaration with @context, type, and proof, the same way a quote is signed, and this route does not accept that wrapper.
//
// When fulfillment_authorization is present, the caller must not also send fulfillment_quote. The request's transaction_hash must equal authorization_used.transaction_hash.
type FulfillmentAuthorization struct {
	// Authorization The EIP-3009 authorization carried on the fulfillment authorization.
	// message is the hash that was signed, and FulfillmentAuthorized.authorizationHash
	// must equal it. veri-fill does not recover the signature.
	Authorization SignedMessage `json:"authorization"`

	// AuthorizationUsed Points at one log. `log_index` is the receipt `logIndex` (index in the block).
	AuthorizationUsed OnchainLogLocator `json:"authorization_used"`

	// Evidence Pointer to the on-chain evidence of the fulfillment authorization.
	Evidence struct {
		// LogIndex Receipt logIndex of the log inside that transaction's block.
		LogIndex int `json:"log_index"`

		// TransactionId Chain transaction identifier. EVM transactions are 0x-prefixed hex, Tron and Stellar transactions are hex without that prefix, and Solana transactions are base58.
		TransactionId string `json:"transaction_id"`
	} `json:"evidence"`

	// FulfillmentQuoteJson Raw JSON of the fulfillment quote (schemas/declarations/FulfillmentQuote/v1/schema.json), including proof metadata so its canonical quote hash can be computed.
	FulfillmentQuoteJson string `json:"fulfillment_quote_json"`

	// Scheme Authorization scheme: EIP-3009 for an EVM destination, SOROBAN-AUTH for a Stellar one.
	Scheme FulfillmentAuthorizationScheme `json:"scheme"`

	// TokenTransfer Points at one log. `log_index` is the receipt `logIndex` (index in the block).
	TokenTransfer OnchainLogLocator `json:"token_transfer"`

	// Version Semver-shaped declaration version (MAJOR.MINOR). The major component is locked to this schema's parent directory (v1 → major must be 1).
	Version string `json:"version"`
}

// FulfillmentAuthorizationScheme Authorization scheme: EIP-3009 for an EVM destination, SOROBAN-AUTH for a Stellar one.
type FulfillmentAuthorizationScheme string

// FulfillmentVerdict A signed attestation of what this service observed on the destination chain, so a
// consumer can act on the signature instead of repeating the chain read.
//
// Distinct from the escrow signature alongside it. The response root's `signature` is
// an EIP-712 release witness consumed by the escrow contract on the SOURCE chain; it
// binds escrow members, carries neither a block nor a transaction, and its typehash is
// fixed by deployed contracts. This object attests DESTINATION-chain observations and
// is consumed offchain only. Two signatures over two structs, by two different keys in
// a cross-chain-family corridor, and neither substitutes for the other.
//
// Also distinct from the fulfillment confirmation a settler reports about its own
// transaction. That is a self-report by the party that sent it; this is a third-party
// attestation by the verifier. Same nouns, different trust level - do not treat one as
// the other.
//
// THEIR MEMBER ENCODINGS DIVERGE ON PURPOSE, and the divergence is recorded here so it
// is not read as drift. That report is consumed as data and may spell a value however
// its own schema allows; every member here is length-prefixed into signed bytes, so each
// admits exactly ONE spelling and a producer normalises to it. Reconciling the two to a
// shared encoding would either widen this object, giving a member several legal
// preimages, or narrow a report that has no signature to protect. A consumer holding both
// MUST normalise the report to this object's forms before comparing them, and MUST NOT
// conclude a mismatch from a difference in spelling alone.
//
// WHAT A NEGATIVE DOES NOT ESTABLISH. A `not_delivered` outcome claims two things: that
// no matching delivery had happened at `block_number`, and that one landing afterwards
// could no longer count. The verifier observes the first. It cannot observe the second,
// because what closes the window is a fulfillment deadline and NO CHAIN RECORDS ONE: it
// is absent from the escrow, from the release witness, from the refund witness and from
// the stored deposit, and reaches the verifier inside the awarded quote.
//
// This object therefore carries NO expiry and NO deadline, and that is deliberate rather
// than an omission. Signing the deadline would present a quote term as a chain
// observation, which is the one thing every member here forbids, and two payments with
// different deadlines would obtain two different signed answers over identical chain
// state. An expiry would put a clock back into a contract whose whole point is that only
// a verdict moves a payment to a terminal state.
//
// What follows for a consumer: A NEGATIVE IS A STATEMENT ABOUT `block_number` AND ABOUT
// NOTHING LATER. It stays true about that block forever and MUST NOT be read as true of
// any later point, so a consumer needing a statement about a later point asks again. And
// because the window cannot be attested, a producer that cannot establish it has closed
// MUST emit `undetermined` instead: a wrong `not_delivered` is terminal, a wrong
// `undetermined` costs one more ask.
//
// WHAT THIS OBJECT DELIBERATELY DOES NOT CARRY, so that a reader does not take the
// absences for oversights:
//
//   - A CONFIRMATION DEPTH. `block_number` and `block_hash` already let anyone with chain
//     access establish depth for themselves, and the check the producer applied, a depth
//     or the chain's finalized tag, is published per chain by GET /v1/finality-config
//     rather than restated here. It also has no meaning on `solana:*`, where finality is a
//     commitment level and not a count, so a required member would be unfillable on one
//     of the three families.
//   - A BLOCK TIMESTAMP. It would only be actionable next to a signed deadline to compare
//     it against, and per the note above there is none. On its own it invites exactly the
//     comparison against an unattested deadline that this object refuses to make.
//   - A SOURCE-CHAIN FACT OF ANY KIND. Those belong to `DepositVerdict`, whose chain
//     member, block members and signing key are all source-scoped. See that object.
//
// OPTIONAL, AND ONLY EVER COMPLETE. A response without a verdict is well-formed and
// means no attestation is available: the service does not evaluate verdicts, or it
// could not reach a signable conclusion. ABSENCE IS NOT AN OUTCOME. A consumer MUST
// NOT read it as delivered, as not-delivered, or as a failure of the payment, and MUST
// fall back to the root `verified` and `error` members.
//
// A verdict is signed only for a conclusion drawn from chain state, and the line that
// decides whether a verdict exists at all is whether a block can be named. Read the
// chain successfully and the answer is attestable even when it is not terminal, which
// is why `outcome` carries `undetermined` alongside the two terminal values: the
// verifier looked, at a named final block, and the window is still open. Fail to read
// the chain and there is no block to anchor anything to, so no verdict is issued and
// the case goes out unsigned through the root `error` as `VERIFICATION_ERROR`. A
// consumer MUST NOT treat either of those as terminal: the payment stays pending and is
// re-asked. NEITHER a client polling budget expiring, NOR an HTTP 5xx, NOR a network
// error is a finding about the payment either, and a consumer MUST NOT derive one from
// any of them.
//
// Do not read the presence of a verdict as a terminal answer, nor its absence as a
// negative one. Both mistakes are available and the members below are written to make
// neither easy.
//
// PRECEDENCE, AND ONLY ONCE VERIFIED. A verdict is attacker-supplied data until its
// signature checks out, so presence alone confers nothing. A consumer MUST first complete
// every step of HOW A THIRD PARTY VERIFIES below; a verdict that fails any step MUST be
// treated as ABSENT, per ABSENCE IS NOT AN OUTCOME above, and never as a negative
// finding. Once verified, a consumer MUST treat the verdict as authoritative over the root
// `verified` and `error`, which predate it and cannot express a signed claim. On the
// release response a verified verdict and the root members agree, in one direction:
// `verified: true` implies `outcome: delivered`, and `outcome: not_delivered` exactly
// when `error` is `FULFILLMENT_NOT_DELIVERED`. The refund response pairs them the other
// way round, because there `verified: true` means a refund was signed: see
// `RefundSignatureResponse.error`.
//
// DELIVERED DOES NOT IMPLY `verified`. `verified` reports whether a release signature was
// issued, not whether the delivery happened, and `DEADLINE_EXCEEDED` is exactly where the two
// part: the recipient was paid, so `outcome` is `delivered`, and the delivery fell outside the
// quote's fulfillment window, so `verified` is FALSE and no `signature` accompanies it. A
// consumer MUST NOT treat that pairing as a contradiction, and MUST NOT read the false
// `verified` as non-delivery. Enforced by the request handler; OpenAPI 3.0.3 expresses no
// cross-member constraint. This service never refuses a delivery for being late, so it
// does not produce that pairing.
//
// EVERY MEMBER IS REQUIRED AND MUST BE SERIALIZED, including when the value is the
// empty string. A producer MUST NOT suppress a member via `omitempty` or an
// equivalent, and a consumer MUST reject a verdict in which any member is absent or
// null BEFORE deriving what was signed. An absent member is not an empty member: a
// renderer that interpolates a missing value produces a preimage containing that
// language's word for undefined, which is a silent verification failure on the
// commonest path rather than a loud one.
//
// SIGNING SCHEME (normative). `signature` covers the members of this object, and what
// it is computed over is DERIVED from them. It is NOT carried on the wire: a consumer
// that verified a signature against bytes it was handed would have verified nothing,
// because an attacker could pair those bytes with unrelated typed members. The form
// follows the chain family, as `signature_scheme` names it.
//
// On `eip155:*` (`eip712-secp256k1`) it is EIP-712 typed data, with the domain given on
// `VerdictSignatureScheme` and the primary type
//
//	`FulfillmentVerdict(string domain,bytes32 paymentId,string chainId,string outcome,uint256 blockNumber,bytes32 blockHash,string finalityPolicy,bytes32 transactionHash,address fulfiller)`
//
// Each field carries the member of the same meaning verbatim: `chainId` is the whole
// CAIP-2 `chain_id` string and `blockNumber` the decimal `block_number`. An empty
// `transaction_hash` is encoded as the zero bytes32 and an empty `fulfiller` as the
// zero address. That is unambiguous because both members are populated exactly when
// `outcome` is `delivered`, and a producer never spells a zero value explicitly. A
// consumer MUST reject an eip155 verdict whose `transaction_hash` or `fulfiller`
// spells the zero value, since it signs the same digest as an empty one. The primary
// type names the attestation kind, so typed data for one kind never hashes to the
// digest of another.
//
// On `tron:*` and `solana:*` it is a preimage. The preimage is UTF-8 and consists of
// exactly TEN lines, each terminated by one LF (0x0A) including the tenth, so it
// contains exactly ten 0x0A bytes and its final byte is 0x0A. 0x0D is never emitted.
// The order is fixed and no other line may appear:
//
//  1. the literal `atum-verdict/fulfillment/1`
//  2. `domain=<n>:<domain>`
//  3. `payment_id=<n>:<payment_id>`
//  4. `chain_id=<n>:<chain_id>`
//  5. `outcome=<n>:<outcome>`
//  6. `block_number=<n>:<block_number>`
//  7. `block_hash=<n>:<block_hash>`
//  8. `finality_policy=<n>:<finality_policy>`
//  9. `transaction_hash=<n>:<transaction_hash>`
//  10. `fulfiller=<n>:<fulfiller>`
//
// `<n>` is the LENGTH IN BYTES of the value that follows, in base-10 with no leading
// zeros, and `<n>:` is present even when the value is empty, which renders as `=0:`
// followed by nothing.
//
// THE PREIMAGE'S FIRST LINE NAMES THE ATTESTATION KIND, not merely the format version,
// and that is load-bearing rather than descriptive. A key this service holds for a chain
// can sign every kind of attestation for that chain. Two kinds sharing a first line would
// share a signing domain, and where their member lists agreed a signature over one would
// satisfy a verifier of the other. A producer
// MUST emit this exact first line and a consumer MUST reject a preimage that does not
// begin with it, rather than accepting any line that merely looks like a verdict tag.
//
// The framing is what makes the rendering injective, and it is worth being precise about
// why. The nine keys are fixed and in fixed order, so no key label is caller-chosen, and
// each `<n>` is digits-only and therefore self-delimited by the first `:` after the key.
// A value may consequently contain a `:` or begin with digits without being absorbed into
// a neighbour. Under a bare `key=value` framing, by contrast, a value carrying an LF can
// reproduce a following line, and two verdicts differing in `chain_id` can render to
// identical bytes so that one signature authenticates both. The byte rejections below
// would also stop that particular pair, since it needs an LF on both sides; the framing
// is what removes the class rather than the instance, and it does so whether or not any
// validator runs. That matters because the patterns in this schema are documentary -
// neither the Go nor the TypeScript bindings validate them at runtime.
//
// Values are used exactly as they appear on the wire, byte for byte, with no case
// folding, re-encoding or address normalization. Each member below admits exactly one
// encoding per chain family for that reason: a consumer that normalizes a value before
// deriving the typed data or preimage will fail to verify. `signature` and
// `signature_scheme` are the envelope and are signed under neither form.
//
// EVERY MEMBER IS PRINTABLE ASCII, 0x20 to 0x7E inclusive, and a producer or consumer
// MUST reject any value carrying a byte outside that range before rendering. This is not
// tidiness: `<n>` counts BYTES, which Go's `len` gives directly but which a naive
// JavaScript renderer using `.length` does not, since that counts UTF-16 code units. A
// single non-ASCII byte therefore makes two good-faith implementations sign different
// preimages for the same verdict, and a homoglyph in a hostname is a realistic
// misconfiguration rather than a contrived input. Restricting the range removes the
// divergence instead of asking every implementation to remember it. The framing bytes
// 0x0A and 0x3D MUST likewise be rejected.
//
// Do NOT delegate these checks to regex anchoring: `$` in Python's `re` and in PCRE
// matches before a trailing newline, so `re.match` and `preg_match` accept a value ending
// in LF that the pattern is written to forbid. Use `re.fullmatch`, `\A...\z`, or an
// explicit byte scan.
//
// HOW A THIRD PARTY VERIFIES, with no chain access, in order, failing closed at the
// first step that does not hold:
//  1. Reject the verdict unless every member is present and matches its pattern.
//  2. Reject unless `payment_id` is the payment this consumer expects. A SIGNATURE
//     PROVES WHAT WAS ATTESTED, NEVER WHICH QUESTION IT ANSWERS: without this step a
//     genuine verdict about another payment passes every remaining step, and one
//     payment's delivery marks another complete.
//  3. Reject unless `chain_id` is the destination chain this consumer asked about.
//     Without this step the verdict chooses its own trust anchor, because step 7
//     fetches a key for whatever chain the verdict names.
//  4. Reject unless `signature_scheme` matches the namespace of `chain_id`, and
//     unless the length of `signature` matches `signature_scheme`.
//  5. Reject unless `domain` equals `did:web:` followed by the lowercased host, without a
//     port, of the fulfillment verifier endpoint the payment names. `domain` is a claim
//     by the signer, not a fact - it is checked against the payment, never trusted as
//     read. Without this step a verdict issued by one deployment verifies as a verdict
//     from another whenever they derive from a shared signing backend.
//  6. Derive what was signed from the members of THIS object: the typed data for
//     `eip712-secp256k1`, the preimage for the other schemes.
//  7. key = GET /v1/public-keys/{chain_id} -> PublicKeyResponse.address, asked of the
//     fulfillment verifier endpoint the payment names.
//  8. Verify per `signature_scheme`, and treat an unrecognised scheme as a rejection
//     rather than falling through to a default.
//
// THE PAYMENT NAMES ITS VERIFIER. A consumer trusts the verifier the payment names and
// keeps no list of its own. Deciding which verifiers are trusted belongs to the settlement operator:
// a settlement operator MUST NOT submit a quote for a payment naming a verifier it does not trust.
//
// STEPS 2 AND 3 COMPARE AGAINST THE FORM THIS SCHEMA REQUIRES, NOT AGAINST THE VALUES THE
// CONSUMER HOLDS. Both members are narrower here than the values a consumer holds:
// `payment_id` than the payment id the consumer holds, and `chain_id` than the
// destination chain as the quote spells it. Each is signed verbatim, length-prefixed
// into the preimage or hashed into the typed data, and a value with several legal
// spellings has several legal signed forms. A consumer that compared these verbatim
// against the values it holds would reject every valid verdict where those values use
// another legal spelling. Normalize the value asked about to the form named on each
// member, then compare.
//
// Nothing in this object may be used in place of step 7. It deliberately carries no
// signer address and no digest, because a member supplying its own trust anchor
// verifies against itself and would accept a verdict signed by any key at all.
type FulfillmentVerdict struct {
	// BlockHash Hash of the block at `block_number`, in the destination chain's native encoding:
	// lowercase 0x-prefixed hex on `eip155:*` and `tron:*`, base58 on `solana:*`. Hex
	// is 0x-prefixed on EVERY chain including `tron:*`, where the bare form is
	// conventional, so that one value has one spelling and therefore one signed form.
	//
	// Present so the observation pins one specific block rather than a height a reorg
	// can repoint. A consumer performs no chain read, but this is what lets anyone
	// with chain access falsify the claim afterwards: if the chain reports a different
	// hash at this height, this verdict described a block that is no longer canonical,
	// and the verdict is void. A void `delivered` verdict does NOT become
	// `not_delivered` - the absence of a valid verdict is never a finding.
	BlockHash string `json:"block_hash"`

	// BlockNumber Height of the block the verdict was evaluated at, as a base-10 string: for
	// `delivered` the block containing `transaction_hash`, for `not_delivered` and
	// `undetermined` the highest block scanned, and on `solana:*` the slot rather than
	// the block height. It MUST be final in every case, including `undetermined`,
	// because a claim anchored to a block a reorg can undo is not attestable.
	// This is the point in chain history the attestation is anchored to.
	//
	// FINAL MEANS FINAL BY THE PRODUCER'S PUBLISHED POLICY AT SIGNING TIME, not by any
	// absolute standard, and that policy CAN CHANGE. The per-chain confirmation floor is
	// served by GET /v1/finality-config, and on some chains it has been as low as a single
	// confirmation. TWO VERDICTS WITH IDENTICAL MEMBERS MAY THEREFORE CARRY DIFFERENT
	// STRENGTH: nothing in the signed bytes records the floor that was in force, so a
	// consumer cannot tell from the verdict alone whether it was evaluated one confirmation
	// deep or twenty, and the floor in force at some past signing time is not recoverable
	// after it moves.
	//
	// What that does NOT undermine is falsifiability. `block_hash` still pins one specific
	// block, so a verdict whose block left the canonical chain is detectable by anyone with
	// chain access, whatever floor produced it. The residual exposure is a verdict that was
	// honestly signed against a shallow floor and is now relied on as though it were deep. A
	// consumer whose own risk bar exceeds the published floor MUST apply its own depth on top
	// rather than treat this member as sufficient.
	//
	// A STRING, not a JSON number, because this member is signed. JSON Schema
	// `type: integer` also matches `123456789.0` and `1.23456789e8`, which a JavaScript
	// parser renders as `123456789` while a Go int64 decode rejects the whole response
	// outright, and values above 2^53-1 lose precision in any IEEE-754 parser. A
	// string has exactly one spelling on the wire and it is the spelling that is
	// signed.
	BlockNumber string `json:"block_number"`

	// ChainId The destination chain the observation was made on, in CAIP-2 format, and the
	// chain whose signing address verifies `signature`. Step 3 rejects a verdict whose
	// `chain_id` is not the chain the consumer asked about, and it compares against the
	// canonical spelling below rather than against the quote's bytes.
	//
	// The namespace is lowercase. THE REFERENCE IS CASE-SENSITIVE AND IS SIGNED
	// VERBATIM: a producer emits the canonical spelling for the chain and a consumer
	// MUST NOT alter it. For `eip155:*` that is the decimal chain id with no leading
	// zeros and never a hex form; for `tron:*` the lowercase cluster name; for
	// `solana:*` the exact mixed-case base58 genesis-hash prefix, whose case is
	// load-bearing because it is encoded into on-chain state. Note that
	// GET /v1/public-keys/{chain_id} resolves case-insensitively and so gives a
	// verifier no signal about which spelling was signed - the spelling in this member
	// is the only authority. When using this value as a path segment, percent-encode `:`
	// as `%3A` if the client does not do so already.
	ChainId string `json:"chain_id"`

	// Domain The deployment that issued this verdict, as a `did:web` identifier, bound into
	// the signed form so a verdict cannot cross between deployments that share a
	// signing backend. A producer MUST set it to `did:web:` followed by the lowercased
	// host, without a port, of the endpoint payments name to reach it, and a consumer
	// MUST compare it to the same value derived from the payment and reject a
	// mismatch.
	//
	// Mechanically the same rule as the `domain` member of a signed envelope proof
	// elsewhere in this protocol, and semantically its INVERSE: there `domain` names the
	// intended verifier and here it names the issuer. Because of that inversion the value
	// space is deliberately kept distinct from the envelopes' network-wide domain, so a
	// captured verdict and a captured envelope can never be read against each other.
	Domain string `json:"domain"`

	// FinalityPolicy The finality rule the producer enforced before signing, so the STRENGTH of this
	// attestation travels with it instead of having to be looked up and then guessed at.
	//
	// Signed, and required, because the alternative is what this member replaces: two
	// verdicts with identical members, one evaluated a single confirmation deep and one
	// twenty, indistinguishable forever. The published floor moves (see
	// GET /v1/finality-config, whose values are raised per chain over time), and the floor in
	// force at some past signing time is not recoverable afterwards, so a consumer holding an
	// old verdict had no way to judge what it was worth.
	//
	// ONE OF TWO FORMS, matching how the chain family actually reaches finality and mirroring
	// the two mutually exclusive members of `ChainFinalityConfig`:
	//
	//   * `confirmations:<n>` on block-depth chains (`eip155:*`, `tron:*`), where `<n>` is a
	//     base-10 depth, with no leading zeros, that the block had reached when the verdict
	//     was signed, counted inclusively. It is always a LOWER BOUND, never an exact figure:
	//     a producer that enforces a confirmation floor states that floor, and one that gates
	//     on the chain's finalized block tag states the depth it observed below a head read
	//     before the block was checked. `confirmations:0` is legal and means the producer
	//     required none, which a consumer SHOULD treat as the weakest possible claim rather
	//     than as a missing value.
	//   * `commitment:<level>` on commitment-based chains (`solana:*`), where `<level>` is the
	//     read commitment confirmed at.
	//
	// A depth is deliberately NOT used for `solana:*`, and a commitment NOT for the others: a
	// count has no meaning where finality is a commitment level, and forcing one shape on both
	// is what makes a single required member unfillable on a family.
	//
	// A consumer MUST NOT reject a verdict merely because this value is weaker than its own
	// bar. The verdict is still an honest report of what was observed. What the consumer MUST
	// do is apply its own additional depth before acting, rather than reading a signed
	// attestation as agreement with its risk appetite.
	FinalityPolicy string `json:"finality_policy"`

	// Fulfiller The destination-chain address that executed the fulfillment, taken from the
	// fulfillment event that was matched at `block_number`.
	//
	// A PRODUCER MUST SOURCE THIS FROM THE OBSERVED EVENT AND MUST NOT ECHO ANY REQUEST
	// MEMBER INTO IT. That is the one thing this object exists not to do: every other
	// member here is an observation, and a value copied from the caller and then signed
	// would be an assertion wearing an attestation's signature. A producer that cannot
	// read the executing address from the event MUST NOT emit a `delivered` verdict.
	//
	// IT MAY LEGITIMATELY DIFFER FROM THE SETTLER THE QUOTE NAMES, so a consumer MUST
	// NOT reject a verdict on that ground alone. The fulfillment entrypoint is
	// permissionless, so whoever paid the recipient is recorded here whether or not it is
	// the settler the payment expected. A delivery by an unexpected address is still a
	// delivery: the recipient has the funds, and who sent them is a matter for settlement
	// accounting rather than for whether the payment happened.
	//
	// It is also NOT the source-chain settler address stored in the deposit's
	// reserveWitness, and the two differ in cross-chain-family
	// corridors. Named `fulfiller` rather than `settler` because this contract already
	// uses that word for both.
	//
	// One encoding per family, narrower than the address pattern used elsewhere in
	// this contract because this member is signed: `eip155:*` is lowercase 20-byte hex
	// with 0x and NEVER the EIP-55 mixed-case form; `tron:*` is base58check beginning
	// `T` and never the 20-byte EVM-equivalent hex or the 21-byte 0x41 form, both of
	// which this protocol's address library otherwise accepts as the same account;
	// `solana:*` is a base58 account.
	//
	// THE EMPTY STRING FOR EVERY OUTCOME EXCEPT `delivered`, on the same rule as
	// `transaction_hash`.
	Fulfiller string `json:"fulfiller"`

	// Outcome What the verifier concluded, and the claim the signature commits to. A verdict
	// answers one question - did the expected delivery happen - and there are three
	// honest answers to it, so all three are values here rather than two values and a
	// silence.
	//
	// `delivered` - the fulfillment was found at the attested block and matched every
	// expected parameter.
	//
	// `not_delivered` - at the attested block, which is final, the expected delivery
	// had not happened AND could no longer count if it landed afterwards. Terminal.
	//
	// `undetermined` - the chain was read successfully to the attested block, which is
	// final, and no matching delivery was found, but a delivery landing after it could
	// still count. NOT terminal: the payment stays pending and is asked again. This is
	// a positive statement about a named block and is signed for that reason, unlike
	// the case below.
	//
	// WHAT SEPARATES THE LAST TWO IS WHETHER THE WINDOW HAS CLOSED, and that rests on
	// a fulfillment deadline which no chain records - see WHAT A NEGATIVE DOES NOT
	// ESTABLISH above. A producer that cannot establish the window has closed MUST emit
	// `undetermined` rather than `not_delivered`, because a wrong `not_delivered` is
	// terminal and a wrong `undetermined` only costs another ask.
	//
	// NOT EVERY UNKNOWN IS A VERDICT. When the chain could not be read at all there is
	// no block to anchor a claim to, so no verdict is issued and the case is reported
	// unsigned through the root `error`. `undetermined` is the opposite situation: the
	// read succeeded and the block is named, which is what makes it attestable.
	//
	// A consumer MUST switch on the value and MUST NOT branch on
	// `outcome != "delivered"`, which would turn both non-terminal answers into a
	// failure. A value this enum does not list MUST be treated as no verdict, and the
	// payment left pending - which is also the correct handling of `undetermined`
	// itself, so a consumer built against an earlier two-value form degrades safely
	// rather than wrongly.
	//
	// THIS SET MAY GROW, and a consumer MUST be written to survive that. What bounds it
	// is not a count but a rule: a value appears here only if it is a conclusion the
	// verifier DREW FROM CHAIN STATE at the block this verdict names. A judgement that
	// needs anything else - a policy, a clock, a value the caller supplied - is reported
	// through the response root instead, unsigned, because signing it would attest as an
	// observation something that was never observed. That is why a late delivery is
	// `delivered` here and late somewhere else, and it is the test to apply to any value
	// proposed for this member.
	Outcome FulfillmentVerdictOutcome `json:"outcome"`

	// PaymentId The escrow deposit this verdict is about, as LOWERCASE 0x-PREFIXED 32-BYTE HEX
	// and no other spelling, because this value is signed verbatim, and a member with
	// several legal spellings has several legal signed forms.
	//
	// NORMALISING TO THAT FORM IS A PRODUCER OBLIGATION, NOT A CONSUMER'S. A consumer
	// performing step 2 normalizes the payment id it holds for its deposit to this form
	// and compares against that.
	PaymentId string `json:"payment_id"`

	// Signature Signature over the typed data or preimage derived per `signature_scheme`, by the
	// key that GET /v1/public-keys/{chain_id} serves for this verdict's `chain_id` - the
	// destination chain, the one the verdict makes claims about, not the source chain
	// whose key signs the escrow release witness in the same response.
	//
	// Lowercase hex WITHOUT an 0x prefix, unlike the escrow `signature` on the enclosing
	// response for `eip155:*` and `tron:*`. The length MUST agree with `signature_scheme`:
	// 130 characters for the two secp256k1 schemes, 128 for `ed25519-raw`. A length
	// inconsistent with the declared scheme MUST be rejected. That agreement is not
	// expressible as a pattern here, since a pattern cannot see a sibling member.
	Signature string `json:"signature"`

	// SignatureScheme The complete signing rule for `signature`, named rather than inferred so that an
	// unrecognised value fails closed at the signature check instead of falling into a
	// consumer's default branch. It names the whole rule and not merely the curve,
	// because the curve was never the ambiguous part: several mutually incompatible
	// secp256k1 message conventions exist in practice and all of them produce a
	// 130-character signature.
	//
	// The mapping is a closed bijection on the `chain_id` namespace - `eip155` to
	// `eip712-secp256k1`, `tron` to `tip191-secp256k1`, `solana` to `ed25519-raw` - and
	// a consumer MUST reject a verdict whose scheme does not match its namespace.
	//
	// `eip712-secp256k1`: 65 bytes, `r || s || v`. Recover the signer over the EIP-712
	// digest `keccak256(0x19 || 0x01 || domainSeparator || hashStruct(message))` of the
	// typed data defined under SIGNING SCHEME on `FulfillmentVerdict` and
	// `DepositVerdict`. The domain type is
	//
	//   `EIP712Domain(string name,string version,uint256 chainId)`
	//
	// with name `Atum Verdict`, version `1` and chainId the decimal reference of the
	// verdict's `chain_id`, and NO `verifyingContract`. A verdict is kept apart from the
	// escrow witnesses the same key signs by its domain name and its type hashes, which no
	// witness shares. A signing policy pins verdicts by `primary_type` together with
	// `domain.name == "Atum Verdict"`.
	//
	// The typed data is signer input only. The verdict object is the canonical form: the
	// message spells an empty member as an explicit zero, and that zero never appears on
	// the wire. Typed data or a digest can be derived from any verdict, so a producer MUST
	// validate the verdict against every member's pattern and the outcome rule before
	// signing.
	//
	// `tip191-secp256k1`: 65 bytes, `r || s || v`. Recover the signer over
	// `keccak256("\x19TRON Signed Message:\n" || decimal(byteLength(preimage)) ||
	// preimage)`. Note the length is in BYTES; the preimage is all-ASCII so a
	// code-unit length coincides, but only because every member's pattern is ASCII.
	//
	// `ed25519-raw`: 64 bytes, verified over the preimage BYTES with no hashing step.
	//
	// For both secp256k1 schemes: `s` MUST be low-s (`s <= n/2`) and a high-s
	// signature MUST be rejected. `v` MUST be normalized on the verify side - subtract
	// 27 if the final byte is at least 27, then require 0 or 1 - because both the
	// `{0,1}` and `{27,28}` forms occur in practice from different signing backends and
	// both recover the same signer. Compare the recovered 20 BYTES to the bytes decoded
	// from the served address; do not compare address strings. Validate the served
	// address separately: for `eip155:*` accept all-lowercase, all-uppercase, or a
	// correctly checksummed EIP-55 string and reject a mixed-case string whose EIP-55
	// checksum is wrong, since that checksum is the only integrity protection on the
	// value the verifier fetched. For `tron:*` base58-decode the served address,
	// require exactly 25 bytes, verify that bytes 21 to 25 are the first four bytes of
	// `sha256(sha256(bytes 0 to 21))`, require byte 0 to be 0x41, and compare bytes 1
	// to 21 - plain base58 yields 25 bytes, not 21, so "strip the 0x41" must not be
	// read as "take everything after byte 0".
	//
	// For `ed25519-raw`: base58-decode the served address and require EXACTLY 32 bytes
	// before verifying, because a short public key makes some implementations panic
	// rather than return false. The signature MUST be canonical per RFC 8032 section
	// 5.1.7 - reading `signature[32:64]` as a little-endian integer `S`, reject unless
	// `S < L` where `L = 2^252 + 27742317777372353535851937790883648493` - and the
	// public key MUST be rejected if small-order or non-canonically encoded. This check
	// is normative and MUST be performed explicitly: widely used Solana libraries omit
	// it while other implementations enforce it, so the same verdict, key and signature
	// verify in one and fail in the other, and any valid signature can be malleated
	// into a second distinct signature over the same verdict.
	//
	// Domain separation for `ed25519-raw` rests entirely on the preimage's first line,
	// because unlike the two secp256k1 schemes it adds no prefix or typed-data domain of
	// its own. That is sufficient against any payload that cannot begin with those bytes,
	// and a key this service holds for a chain also signs escrow witnesses for that chain
	// when it is the source. A signer MUST therefore never raw-sign a
	// payload whose leading bytes are any `atum-verdict/<kind>/<version>` line followed by
	// LF for any purpose other than an attestation of that kind.
	SignatureScheme VerdictSignatureScheme `json:"signature_scheme"`

	// TransactionHash The fulfill transaction that was verified, on the chain in `chain_id`: a
	// lowercase 0x-prefixed EVM transaction hash, a 0x-prefixed Tron transaction id,
	// or a base58 Solana signature. On the release response it is the same transaction the
	// request named, now attested rather than merely accepted as input. On the refund
	// response no transaction is requested, and it is the one the destination scan found.
	// Either way it is what lets an originator check the claim independently. It is not an
	// echo: see the normalization note below.
	//
	// NARROWER THAN THE REQUEST MEMBER OF THE SAME NAME, which also accepts mixed-case
	// hex and the bare 64-character Tron form. Echoing a request value verbatim can
	// therefore produce a verdict that fails its own pattern, so normalising to the single
	// form above is a producer obligation, not a consumer's.
	//
	// THE EMPTY STRING FOR EVERY OUTCOME EXCEPT `delivered`, where there is no
	// transaction to name. Required and always serialized even then, so the signed
	// form has one shape; enforced by the request handler, since OpenAPI 3.0.3 cannot
	// make one member conditional on another's value.
	//
	// A consumer MUST gate on `outcome` before reading this member and MUST NOT
	// propagate an empty value into any payer-facing transaction reference. An empty
	// hash presented as a receipt is indistinguishable from a delivered one that
	// nobody recorded, and a nullish guard does not catch it.
	TransactionHash string `json:"transaction_hash"`
}

// FulfillmentVerdictOutcome What the verifier concluded, and the claim the signature commits to. A verdict
// answers one question - did the expected delivery happen - and there are three
// honest answers to it, so all three are values here rather than two values and a
